package com.sympauthy.business.model.mfa

/**
 * The kind of second factor an MFA method is, which the flow offers an end-user to enroll or to pass and the
 * admin surface names on each MFA method a user has enrolled.
 */
enum class MfaMethodType {
    /**
     * A time-based one-time password, generated by an authenticator app from a seed shared at enrollment.
     */
    TOTP
}
